```python
import requests

def get_subdomains(domain):
    try:
        response = requests.get(f'https://crt.sh/?q={domain}')
        if response.status_code == 200:
            return response.text.split('\n')
        else:
            print(f"Failed to retrieve data: {response.status_code}")
            return []
    except Exception as e:
        print(f"An error occurred: {e}")
        return []

def filter_subdomains(subdomains, domain):
    filtered_subdomains = [sub for sub in subdomains if '.'.join(sub.split('.')[-2:]) == domain]
    return filtered_subdomains

if __name__ == "__main__":
    domain = "example.com"  # Replace with the domain you want to query
    raw_subdomains = get_subdomains(domain)
    subdomains = filter_subdomains(raw_subdomains, domain)

    if subdomains:
        print(f"Subdomains found under {domain}:")
        for sub in subdomains:
            print(sub.strip())
    else:
        print("No subdomains found.")
```

This script uses the crt.sh API to fetch all SSL certificates associated with a given domain and then filters out the subdomains that match the specified domain. Replace "example.com" with the domain you want to query.

