      name
    }
    mutationType {
      name
    }
    subscriptionType {
      name
    }
    types {
      name
      kind
      fields {
        name
        type {
          name
          kind
        }
      }
    }
    directives {
      name
      locations {
        __enumValue
      }
    }
  }
}
"""

# Function to perform the introspection query and return the schema
def get_graphql_schema(url, query):
    headers = {'Content-Type': 'application/json'}
    response = requests.post(url, json={'query': query}, headers=headers)
    if response.status_code == 200:
        return response.json()
    else:
        print(f"Error: {response.status_code} - {response.text}")
        return None

# Fetch the schema
